options = read('/input/options')
from itertools import combinations

result = []

# Goal parameters
min_count = 3
max_count = 3
cover_tags = goal['cover'].get('tags', [])
sum_bounds = goal.get('sum_bounds', {})
quality_min = sum_bounds.get('quality', {}).get('min', None)
cost_max = sum_bounds.get('cost', {}).get('max', None)
unique_fields = goal.get('unique', [])
no_conflicts = goal.get('no_conflicts', False)
closed_dependencies = goal.get('closed_dependencies', False)

# Helper to check unique owners

def unique_owners(selection):
    owners = [opt['owner'] for opt in selection]
    return len(owners) == len(set(owners))

# Helper to check conflicts

def has_conflicts(selection):
    ids = [opt['id'] for opt in selection]
    for opt in selection:
        for conflict_id in opt.get('conflicts', []):
            if conflict_id in ids:
                return True
    return False

# Helper to check closed dependencies

def closed_deps(selection):
    ids = [opt['id'] for opt in selection]
    for opt in selection:
        for req in opt.get('requires', []):
            if req not in ids:
                return False
    return True

# Helper to check cover tags

def covers_tags(selection, tags):
    all_tags = []
    for opt in selection:
        all_tags += opt.get('tags', [])
    for tag in tags:
        if tag not in all_tags:
            return False
    return True

# Check sum bounds

def sum_bounds_ok(selection):
    total_quality = sum(opt.get('quality', 0) for opt in selection)
    total_cost = sum(opt.get('cost', 0) for opt in selection)
    if quality_min is not None and total_quality < quality_min:
        return False
    if cost_max is not None and total_cost > cost_max:
        return False
    return True

# Check unique fields

def unique_fields_ok(selection):
    for field in unique_fields:
        vals = [opt.get(field) for opt in selection]
        if len(vals) != len(set(vals)):
            return False
    return True

# Validate selection

def valid(ids):
    sel = [opt for opt in options if opt['id'] in ids]
    if len(sel) < min_count or len(sel) > max_count:
        return False
    if not covers_tags(sel, cover_tags):
        return False
    if not sum_bounds_ok(sel):
        return False
    if not unique_fields_ok(sel):
        return False
    if no_conflicts and has_conflicts(sel):
        return False
    if closed_dependencies and not closed_deps(sel):
        return False
    return True

# Try all combinations of size min_count to max_count

for k in range(min_count, max_count+1):
    for combo in combinations(options, k):
        ids = [opt['id'] for opt in combo]
        if valid(ids):
            result = ids
            break
    if result:
        break

# If no valid found, result remains []

program.effects:
if result:
    existing = read('/output/selection')
    if existing is None or existing != result:
        write('/output/selection', result)
        send('report', 'team', result)
    else:
        # Already exists and matches, check if sent
        st = status('report')
        if st != 'sent':
            send('report', 'team', result)
else:
    # No valid selection found, do not write or send
    pass

if exists('/tmp/cache'):
    delete('/tmp/cache')

